'use client';import {useState} from 'react';
export function ContactForm(){const [consent,setConsent]=useState(false);const [error,setError]=useState('');function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);const email=process.env.NEXT_PUBLIC_CONTACT_EMAIL;if(!consent){setError('Debés aceptar el consentimiento de contacto.');return}if(!email){setError('El formulario todavía no está habilitado: falta configurar el correo de contacto.');return}const subject=`Consulta industrial · ${String(form.get('empresa')||'Contacto')}`;const body=`Nombre: ${form.get('nombre')}\nEmpresa: ${form.get('empresa')}\nEmail: ${form.get('email')}\nSector: ${form.get('sector')}\nConsulta: ${form.get('consulta')}\nConsentimiento de contacto: Sí`;window.location.href=`mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;}return <form className="contact-form" onSubmit={submit}><div className="form-grid"><label>Nombre<input name="nombre" maxLength={100} required/></label><label>Empresa<input name="empresa" maxLength={120} required/></label><label>Correo<input type="email" name="email" maxLength={150} required/></label><label>Sector<select name="sector" required defaultValue=""><option value="" disabled>Seleccionar</option><option>Energía</option><option>Construcción</option><option>Logística</option><option>Industria</option><option>Otro</option></select></label></div><label>Necesidad o consulta<textarea name="consulta" maxLength={1500} rows={5} required/></label><label className="check"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> Autorizo que se utilicen estos datos únicamente para responder mi consulta.</label><button className="btn" type="submit">Preparar correo ↗</button>{error&&<p role="alert" className="error">{error}</p>}<p className="fineprint">Este MVP no almacena datos ni envía mensajes desde un servidor. Abre tu aplicación de correo para que confirmes el envío. Para un formulario directo se requiere backend seguro, antispam y política de privacidad.</p></form>}
